        let raw = "some avg10=1.25 avg60=0.80 avg300=0.40 total=12345\nfull avg10=0.00 avg60=0.00 avg300=0.00 total=1\n";
        assert!((parse_psi_some_avg10(raw).unwrap() - 1.25).abs() < 1e-9);
    }

    #[test]
