//! Read-only inventory for operators.

use serde::Serialize;

use crate::collect::{ollama_tags_ok, ollama_version};
use crate::config::AgentConfig;
use crate::listen::{format_host_port, resolve_bind, AddrSource, HostAddrs};

#[derive(Serialize)]
pub struct DoctorReport {
    pub os: String,
    pub arch: String,
    pub gpu_backend: String,
    pub ollama_installed: bool,
    pub ollama_running: bool,
    pub ollama_version: Option<String>,
    pub ollama_listen: String,
    pub agent_listen: String,
    pub tailscale_ok: bool,
    pub notes: Vec<String>,
}

pub async fn run(config: &AgentConfig) -> anyhow::Result<DoctorReport> {
    let token_set = config.bearer_token().is_some();
    let addrs = HostAddrs;
    let addrs: &dyn AddrSource = &addrs;
    let mut notes = Vec::new();
    let ollama_ip = match resolve_bind(&config.ollama.listen, addrs, token_set) {
        Ok(ip) => ip,
        Err(err) => {
            notes.push(err.to_string());
            std::net::IpAddr::V4(std::net::Ipv4Addr::LOCALHOST)
        }
    };
    let agent_ip = match resolve_bind(&config.listen, addrs, token_set) {
        Ok(ip) => ip,
        Err(err) => {
            notes.push(err.to_string());
            std::net::IpAddr::V4(std::net::Ipv4Addr::LOCALHOST)
        }
    };
    let ollama_listen = format_host_port(ollama_ip, 11434);
    let agent_listen = format_host_port(agent_ip, config.port);
    let version = ollama_version().await;
    let running = ollama_tags_ok(&format!("http://{ollama_listen}")).await;
    let snap = crate::collect::collect_live(config, &ollama_listen, None).await;
    if cfg!(windows) {
        notes.push(
            "Windows: do not also run the tray app on :11434; NVIDIA services usually need LocalSystem"
                .into(),
        );
    }
    if cfg!(target_os = "macos") {
        notes.push(
            "macOS LaunchDaemon often runs as root; GPU backend is Metal (no nvidia-smi)".into(),
        );
    }
    let ts = addrs_have_tailscale();
    Ok(DoctorReport {
        os: std::env::consts::OS.into(),
        arch: std::env::consts::ARCH.into(),
        gpu_backend: snap.status.gpu_backend.as_str().into(),
        ollama_installed: version.is_some(),
        ollama_running: running,
        ollama_version: version,
        ollama_listen,
        agent_listen,
        tailscale_ok: ts,
        notes,
    })
}

fn addrs_have_tailscale() -> bool {
    let addrs = HostAddrs;
    let addrs: &dyn AddrSource = &addrs;
    addrs
        .ipv4s()
        .into_iter()
        .any(crate::listen::is_tailscale_ipv4)
}

//! Axum 0.8 app: `/healthz`, `/v1/capacity`, `/v1/pressure`, `/v1/status`, `/metrics`.

use std::sync::Arc;
use std::time::{Duration, Instant};

use axum::extract::State;
use axum::http::{header, HeaderMap, StatusCode};
use axum::response::{IntoResponse, Response};
use axum::routing::get;
use axum::{Json, Router};
use ollama_capacity_types::{CapacityReport, PressureEnvelope};
use serde::Serialize;
use sysinfo::System;
use tokio::sync::RwLock;
use tower_http::request_id::{MakeRequestUuid, PropagateRequestIdLayer, SetRequestIdLayer};
use tower_http::trace::TraceLayer;

use crate::collect::StatusPayload;
use crate::config::AgentConfig;
use crate::metrics::{AgentMetrics, METRICS_CONTENT_TYPE};

const COLLECT_TTL: Duration = Duration::from_secs(2);

#[derive(Clone)]
pub struct CachedSnapshot {
    pub snap: crate::collect::Snapshot,
    pub at: Instant,
}

#[derive(Clone)]
pub struct AppState {
    pub config: Arc<AgentConfig>,
    pub ollama_listen: String,
    pub metrics: Arc<AgentMetrics>,
    pub last: Arc<RwLock<Option<CachedSnapshot>>>,
    pub cpu_usage_pct: Arc<std::sync::RwLock<Option<f64>>>,
}

fn require_token(expected: Option<&str>, headers: &HeaderMap) -> bool {
    let Some(token) = expected.filter(|t| !t.is_empty()) else {
        return true;
    };
    let Some(auth) = headers
        .get(header::AUTHORIZATION)
        .and_then(|v| v.to_str().ok())
    else {
        return false;
    };
    let bearer = auth.strip_prefix("Bearer ").unwrap_or(auth);
    bearer == token
}

#[derive(Serialize)]
struct HealthResponse {
    status: String,
    version: String,
}

async fn healthz() -> Json<HealthResponse> {
    Json(HealthResponse {
        status: "ok".into(),
        version: env!("CARGO_PKG_VERSION").into(),
    })
}

async fn snapshot(state: &AppState) -> crate::collect::Snapshot {
    {
        let guard = state.last.read().await;
        if let Some(cached) = guard.as_ref() {
            if cached.at.elapsed() < COLLECT_TTL {
                return cached.snap.clone();
            }
        }
    }
    let mut guard = state.last.write().await;
    if let Some(cached) = guard.as_ref() {
        if cached.at.elapsed() < COLLECT_TTL {
            return cached.snap.clone();
        }
    }
    let cpu = state.cpu_usage_pct.read().ok().and_then(|slot| *slot);
    let snap = crate::collect::collect_live(&state.config, &state.ollama_listen, cpu).await;
    state.metrics.observe(&snap);
    *guard = Some(CachedSnapshot {
        snap: snap.clone(),
        at: Instant::now(),
    });
    snap
}

async fn capacity(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> Result<Json<CapacityReport>, StatusCode> {
    if !require_token(state.config.bearer_token(), &headers) {
        return Err(StatusCode::UNAUTHORIZED);
    }
    Ok(Json(snapshot(&state).await.report))
}

async fn pressure(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> Result<Json<PressureEnvelope>, StatusCode> {
    if !require_token(state.config.bearer_token(), &headers) {
        return Err(StatusCode::UNAUTHORIZED);
    }
    Ok(Json(snapshot(&state).await.envelope))
}

async fn status(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> Result<Json<StatusPayload>, StatusCode> {
    if !require_token(state.config.bearer_token(), &headers) {
        return Err(StatusCode::UNAUTHORIZED);
    }
    Ok(Json(snapshot(&state).await.status))
}

}

async fn status(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> Result<Json<StatusPayload>, StatusCode> {
    if !require_token(state.config.bearer_token(), &headers) {
        return Err(StatusCode::UNAUTHORIZED);
    }
    Ok(Json(snapshot(&state).await.status))
}

async fn metrics(State(state): State<AppState>) -> Response {
    let _ = snapshot(&state).await;
    match state.metrics.encode_text() {
        Ok(body) => ([(header::CONTENT_TYPE, METRICS_CONTENT_TYPE)], body).into_response(),
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

pub fn make_app(state: AppState) -> Router {
    Router::new()
        .route("/healthz", get(healthz))
        .route("/v1/capacity", get(capacity))
        .route("/v1/pressure", get(pressure))
        .route("/v1/status", get(status))
        .route("/metrics", get(metrics))
        .layer(TraceLayer::new_for_http())
        .layer(PropagateRequestIdLayer::x_request_id())
        .layer(SetRequestIdLayer::x_request_id(MakeRequestUuid))
        .with_state(state)
}

fn spawn_cpu_sampler(slot: Arc<std::sync::RwLock<Option<f64>>>) {
    tokio::spawn(async move {
        let mut sys = System::new();
        sys.refresh_cpu_all();
        loop {
            tokio::time::sleep(Duration::from_secs(1)).await;
            sys.refresh_cpu_all();
            let pct = f64::from(sys.global_cpu_usage());
            if let Ok(mut guard) = slot.write() {
                *guard = Some(pct);
            }
        }
    });
}

pub async fn serve(
    config: AgentConfig,
    bind: std::net::SocketAddr,
    ollama_listen: String,
) -> anyhow::Result<()> {
    if matches!(bind.ip(), std::net::IpAddr::V4(v) if v.is_unspecified())
        && config.bearer_token().is_none()
    {
        anyhow::bail!("listen all requires a bearer token");
    }
    let metrics = Arc::new(AgentMetrics::new()?);
    let cpu_usage_pct = Arc::new(std::sync::RwLock::new(None));
    spawn_cpu_sampler(Arc::clone(&cpu_usage_pct));
    let state = AppState {
        config: Arc::new(config.clone()),
        ollama_listen,
        metrics,
        last: Arc::new(RwLock::new(None)),
        cpu_usage_pct,
    };
    let app = make_app(state.clone());
    crate::register::spawn_if_configured(state);
    let listener = tokio::net::TcpListener::bind(bind).await?;
    tracing::info!(addr = %bind, "ollama-node-agent listening");
    axum::serve(listener, app).await?;
    Ok(())
}

//! Prometheus text for the node agent. No model names.

use prometheus::{Gauge, Histogram, HistogramOpts, IntGauge, Registry, TextEncoder};

pub struct AgentMetrics {
    registry: Registry,
    ollama_up: IntGauge,
    ollama_models: IntGauge,
    vram_gb: Gauge,
    ram_available_gb: Gauge,
    ram_available_known: IntGauge,
    gpu_util: Gauge,
    gpu_util_known: IntGauge,
    vram_free_known: IntGauge,
    collect_seconds: Histogram,
}

impl AgentMetrics {
    pub fn new() -> Result<Self, prometheus::Error> {
        let registry = Registry::new();
        let ollama_up = IntGauge::new("ollama_up", "1 if GET /api/tags succeeded")?;
        let ollama_models = IntGauge::new(
            "ollama_models",
            "On-disk model count from GET /api/tags (no names)",
        )?;
        let vram_gb = Gauge::new("ollama_gpu_vram_gb", "Sum of GPU VRAM (GiB)")?;
        let ram_available_gb = Gauge::new("ram_available_gb", "Available RAM (GiB)")?;
        let ram_available_known = IntGauge::new(
            "ollama_node_agent_ram_available_known",
            "1 if ram_available_gb was measured",
        )?;
        let gpu_util = Gauge::new("gpu_utilization_pct", "Mean GPU utilization percent")?;
        let gpu_util_known = IntGauge::new(
            "ollama_node_agent_gpu_util_known",
            "1 if gpu_utilization_pct was measured",
        )?;
        let vram_free_known = IntGauge::new(
            "ollama_node_agent_vram_free_known",
            "1 if free VRAM was measured (0 can be a full GPU)",
        )?;
        let collect_seconds = Histogram::with_opts(HistogramOpts::new(
            "agent_collect_seconds",
            "Wall time of the last collect",
        ))?;
        registry.register(Box::new(ollama_up.clone()))?;
        registry.register(Box::new(ollama_models.clone()))?;
        registry.register(Box::new(vram_gb.clone()))?;
        registry.register(Box::new(ram_available_gb.clone()))?;
        registry.register(Box::new(ram_available_known.clone()))?;
        registry.register(Box::new(gpu_util.clone()))?;
        registry.register(Box::new(gpu_util_known.clone()))?;
        registry.register(Box::new(vram_free_known.clone()))?;
        registry.register(Box::new(collect_seconds.clone()))?;
        Ok(Self {
            registry,
            ollama_up,
            ollama_models,
            vram_gb,
            ram_available_gb,
            ram_available_known,
            gpu_util,
            gpu_util_known,
            vram_free_known,
            collect_seconds,
        })
    }

    pub fn observe(&self, snap: &crate::collect::Snapshot) {
        self.ollama_up.set(i64::from(snap.status.ollama_running));
        self.ollama_models.set(snap.status.models_on_disk as i64);
        self.vram_gb.set(snap.report.vram_gb);
        let ram = snap
            .report
            .pressure
            .as_ref()
            .and_then(|p| p.ram_available_gb);
        self.ram_available_gb.set(ram.unwrap_or(0.0));
        self.ram_available_known.set(i64::from(ram.is_some()));
        let utils: Vec<f64> = snap
            .report
            .gpus_detail
            .iter()
            .filter_map(|g| g.utilization_gpu_pct)
            .collect();
        let util_known = !utils.is_empty();
        let util = if util_known {
            utils.iter().sum::<f64>() / utils.len() as f64
        } else {
            0.0
        };
        self.gpu_util.set(util);
        self.gpu_util_known.set(i64::from(util_known));
        self.vram_free_known
            .set(i64::from(snap.report.vram_free_is_known()));
        self.collect_seconds.observe(snap.collect_seconds);
    }

    pub fn encode_text(&self) -> Result<String, prometheus::Error> {
        TextEncoder::new().encode_to_string(&self.registry.gather())
    }
}

